set -euo pipefail
trap 'echo "!!! STOPPED at line $LINENO: $BASH_COMMAND" >&2' ERR
P=intel-vault-510704; RG=asia-east1; B=$P-vault; SA=intel-writer@$P.iam.gserviceaccount.com
gcloud config set project $P >/dev/null
echo "== 部署台灣機房測試程式（asia-east1 彰化）"
gcloud run jobs deploy tw-probe --image=docker.io/library/python:3.12-slim --region=$RG --service-account=$SA --set-env-vars=BUCKET=$B --command=sh --args="-c,echo  | base64 -d | python" --task-timeout=300 --max-retries=0 --memory=512Mi --quiet
echo "== 執行（約 1～2 分鐘）"
gcloud run jobs execute tw-probe --region=$RG --wait
sleep 15
echo "== 結果"
gcloud logging read 'resource.type="cloud_run_job" AND resource.labels.job_name="tw-probe" AND textPayload:"PROBE"' --freshness=20m --limit=80 --format='value(textPayload)' | tac
echo "=====DONE====="
